CREATE OR REPLACE FUNCTION public.combat_effect_v2_ally_to(p_state jsonb, p_to text)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object('side', 'card', 'id', q.id::numeric)
    from combat_v2_units(p_state) q
